'use client';

import { useState, useEffect } from 'react';
import { KDSOrder } from '../../types/kds';
import { OrderDetailModal } from '../modals/OrderDetailModal';

interface Props {
    order: KDSOrder;
    variant?: 'standard' | 'expo';
}

export function OrderTicket({ order }: Props) {
    const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
    const [isDelayModalOpen, setIsDelayModalOpen] = useState(false);
    const [isMessagingModalOpen, setIsMessagingModalOpen] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const {
        advanceStage,
        toggleItemCompletion
    } = useKDSStore();
    const { playSound } = useKDSSound();
    const { role: authRole } = useAuth();

    // Live SLA tracking for header background colors
    const [slaState, setSlaState] = useState<'ON_TIME' | 'WARNING' | 'OVERDUE'>(
        getSLAState(order.createdAt, order.prepTimeMinutes)
    );

    useEffect(() => {
        const interval = setInterval(() => {
            const newState = getSLAState(order.createdAt, order.prepTimeMinutes);
            if (newState !== slaState) setSlaState(newState);
        }, 5000); // 5s is enough for background updates
        return () => clearInterval(interval);
    }, [order.createdAt, order.prepTimeMinutes, slaState]);

    const getHeaderBg = () => {
        if (order.isHeld) return 'bg-slate-800';
        switch (slaState) {
            case 'OVERDUE': return 'bg-red-600 text-white';
            case 'WARNING': return 'bg-amber-500 text-black';
            default: return 'bg-slate-900 text-white';
        }
    };

    const handleAdvance = () => {
        if (isProcessing) return;
        setIsProcessing(true);
        playSound('ORDER_UPDATED', order.id);
        advanceStage(order.id);
        setIsProcessing(false);
    };

    const handleItemToggle = (e: React.MouseEvent, itemId: string) => {
        e.stopPropagation();
        toggleItemCompletion(order.id, itemId);
        playSound('ORDER_UPDATED');
    };

    const isUberDirect = order.order_source === 'UBER_DIRECT';

    return (
        <>
            <div
                onClick={handleAdvance}
                className={`kds-ticket h-full bg-[var(--kds-bg-card)] rounded-none flex flex-col overflow-hidden select-none active:brightness-125 border-r border-slate-800/50 ${isProcessing ? 'opacity-50' : ''} ${isUberDirect ? 'border-l-[8px] border-l-emerald-500' : ''}`}
            >
                {/* HIGH VISIBILITY HEADER */}
                <div className={`p-4 flex justify-between items-center transition-colors duration-500 ${getHeaderBg()}`}>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-70">Order ID:</span>
                        <h2 className="font-black text-4xl leading-none tracking-tighter">
                            #{order.orderNumber}
                        </h2>
                    </div>

                    <div className="flex flex-col items-end">
                        <TicketTimer
                            createdAt={order.createdAt}
                            prepTimeMinutes={order.prepTimeMinutes}
                            stageStartedAt={order.stageStartedAt}
                        />
                    </div>
                </div>

                {/* STATUS BAR (Secondary Info) */}
                <div className="px-4 py-2 bg-slate-950/40 border-y border-slate-800 flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                    <div className="flex gap-4">
                        <span className="text-slate-500">Source: <span className="text-white">{order.order_source}</span></span>
                        <span className="text-slate-500">Type: <span className="text-white">{order.fulfillment_type.replace('_', ' ')}</span></span>
                    </div>
                    <div className={`px-2 py-0.5 rounded ${order.isHeld ? 'bg-amber-500 text-black' : 'bg-slate-800 text-slate-400'}`}>
                        {order.isHeld ? 'PAUSED' : order.stage}
                    </div>
                </div>

                {/* ITEM LIST - MAX READABILITY */}
                <div className="p-4 flex-1 overflow-y-auto space-y-3">
                    {order.items.map((item) => (
                        <div
                            key={item.id}
                            onClick={(e) => handleItemToggle(e, item.id)}
                            className={`flex items-start gap-4 p-3 rounded-xl transition-all border-2 ${item.isCompleted ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-slate-800/20 border-transparent hover:border-slate-700'}`}
                        >
                            {/* QUANTITY FIRST */}
                            <div className={`flex-none w-12 h-12 rounded-lg flex items-center justify-center font-black text-2xl ${item.isCompleted ? 'bg-emerald-500 text-white' : 'bg-slate-800 text-amber-500 border border-slate-700'}`}>
                                {item.isCompleted ? <div className="text-xl">✓</div> : `${item.quantity}x`}
                            </div>

                            <div className="flex-1">
                                <h3 className={`font-black text-2xl uppercase leading-tight ${item.isCompleted ? 'text-slate-500 line-through' : 'text-white'}`}>
                                    {item.name}
                                </h3>
                                {item.variant && (
                                    <span className="text-sm font-bold text-slate-500 uppercase tracking-widest block mt-0.5">
                                        {item.variant}
                                    </span>
                                )}

                                {/* MODIFIERS */}
                                {item.modifiers.length > 0 && !item.isCompleted && (
                                    <div className="mt-2 space-y-1">
                                        {item.modifiers.map((mod, midx) => (
                                            <div key={midx} className="flex gap-2 text-sm font-bold text-slate-400 uppercase tracking-tighter">
                                                <span className="text-blue-500">+</span>
                                                <span>{mod.name}</span>
                                                {mod.quantity && mod.quantity > 1 && <span>(x{mod.quantity})</span>}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}

                    {/* ALLERGIES & NOTES */}
                    {(order.allergies?.length || 0) > 0 && (
                        <div className="mt-4 p-4 bg-red-600 border-4 border-white text-white rounded-none animate-pulse">
                            <span className="block text-xs font-black uppercase tracking-widest">⚠️ Allergy Alert</span>
                            <span className="block text-xl font-black uppercase mt-1">{order.allergies?.join(', ')}</span>
                        </div>
                    )}

                    {order.notes && (
                        <div className="mt-4 p-4 bg-blue-600/20 border-l-4 border-blue-500 rounded-r-xl">
                            <span className="block text-xs font-black text-blue-400 uppercase tracking-widest">Notes</span>
                            <p className="text-white font-bold uppercase text-lg mt-1">{order.notes}</p>
                        </div>
                    )}
                </div>

                {/* BOTTOM ACTION - BUMP */}
                <div className="p-3 bg-slate-900 border-t border-slate-800">
                    <button
                        onClick={(e) => { e.stopPropagation(); handleAdvance(); }}
                        disabled={isProcessing}
                        className={`w-full py-4 font-black uppercase tracking-[0.2em] text-lg rounded-2xl transition-all active:scale-95 ${order.stage === 'READY' ? 'bg-white text-black shadow-[0_0_30px_rgba(255,255,255,0.2)]' : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700 border border-slate-700'}`}
                    >
                        {isProcessing ? 'Syncing...' : (order.stage === 'READY' ? 'Bump Order' : `Move to ${order.stage === 'ACCEPTED' ? 'Prep' : 'Next'}`)}
                    </button>
                </div>
            </div>

            <DelayOrderModal
                isOpen={isDelayModalOpen}
                onClose={() => setIsDelayModalOpen(false)}
                onConfirm={() => { }} // Placeholder as direct interaction is minimized
                orderNumber={order.orderNumber}
            />

            <CustomerMessagingModal
                isOpen={isMessagingModalOpen}
                order={order}
                onClose={() => setIsMessagingModalOpen(false)}
                onSend={() => { }}
                role={authRole as KDSRole || 'KDS_USER'}
            />
        </>
    );
}
